module sync_fifo_tb; reg clk=0,rst_n=0,wr_en=0,rd_en=0;reg [7:0] din=0;wire [7:0] dout;wire full,empty;wire [4:0] count;sync_fifo #(.WIDTH(8),.DEPTH(16)) dut(clk,rst_n,wr_en,rd_en,din,dout,full,empty,count);always #5 clk=~clk;initial begin #12 rst_n=1;@(negedge clk);din=8'hA5;wr_en=1;@(negedge clk);wr_en=0;rd_en=1;@(negedge clk);rd_en=0;if(dout!==8'hA5)$fatal(1,"FIFO read mismatch");$display("FIFO tests passed");$finish;end endmodule
